"use strict";

// For auth/change-password pages that only have light/dark theme buttons,
// we bypass the full switcher to avoid null-ref crashes on missing DOM elements.
// The theme toggle is handled by inline <script> in the view.

let mainContent;
(function () {
    let html = document.querySelector('html');
    mainContent = document.querySelector('.main-content');
    localStorageBackup2();

    // Only run the full switcher on pages that have the full switcher panel
    if (document.querySelector('#switcher-panel') !== null) {
        switcherClick();
    }

    checkOptions();
    setTimeout(() => { checkOptions(); }, 1000);
})();

function safeOn(el, event, handler) {
    if (el && typeof el.addEventListener === 'function') {
        el.addEventListener(event, handler);
    }
}

function switcherClick() {
    let html = document.querySelector('html');

    let lightBtn = document.querySelector('#switcher-light-theme');
    let darkBtn  = document.querySelector('#switcher-dark-theme');
    let ltrBtn   = document.querySelector('#switcher-ltr');
    let rtlBtn   = document.querySelector('#switcher-rtl');
    let vBtn     = document.querySelector('#switcher-vertical');
    let hBtn     = document.querySelector('#switcher-horizontal');
    let dwBtn    = document.querySelector('#switcher-default-width');
    let bxBtn    = document.querySelector('#switcher-boxed');
    let fwBtn    = document.querySelector('#switcher-full-width');
    let fmBtn    = document.querySelector('#switcher-menu-fixed');
    let smBtn    = document.querySelector('#switcher-menu-scroll');
    let fhBtn    = document.querySelector('#switcher-header-fixed');
    let shBtn    = document.querySelector('#switcher-header-scroll');
    let lhBtn    = document.querySelector('#switcher-header-light');
    let dhBtn    = document.querySelector('#switcher-header-dark');
    let chBtn    = document.querySelector('#switcher-header-primary');
    let ghBtn    = document.querySelector('#switcher-header-gradient');
    let thBtn    = document.querySelector('#switcher-header-transparent');
    let lmBtn    = document.querySelector('#switcher-menu-light');
    let dmBtn    = document.querySelector('#switcher-menu-dark');
    let cmBtn    = document.querySelector('#switcher-menu-primary');
    let gmBtn    = document.querySelector('#switcher-menu-gradient');
    let tmBtn    = document.querySelector('#switcher-menu-transparent');
    let regBtn   = document.querySelector('#switcher-regular');
    let clsBtn   = document.querySelector('#switcher-classic');
    let modBtn   = document.querySelector('#switcher-modern');
    let flatBtn  = document.querySelector('#switcher-flat');
    let defBtn   = document.querySelector('#switcher-default-menu');
    let mcBtn    = document.querySelector('#switcher-menu-click');
    let mhBtn    = document.querySelector('#switcher-menu-hover');
    let icBtn    = document.querySelector('#switcher-icon-click');
    let ihBtn    = document.querySelector('#switcher-icon-hover');
    let clBtn    = document.querySelector('#switcher-closed-menu');
    let itBtn    = document.querySelector('#switcher-icontext-menu');
    let ovBtn    = document.querySelector('#switcher-icon-overlay');
    let dbBtn    = document.querySelector('#switcher-double-menu');
    let dtBtn    = document.querySelector('#switcher-detached');
    let rstBtn   = document.querySelector('#resetbtn');
    let p1Btn    = document.querySelector('#switcher-primary');
    let p2Btn    = document.querySelector('#switcher-primary1');
    let p3Btn    = document.querySelector('#switcher-primary2');
    let p4Btn    = document.querySelector('#switcher-primary3');
    let p5Btn    = document.querySelector('#switcher-primary4');
    let bg1Btn   = document.querySelector('#switcher-background');
    let bg2Btn   = document.querySelector('#switcher-background1');
    let bg3Btn   = document.querySelector('#switcher-background2');
    let bg4Btn   = document.querySelector('#switcher-background3');
    let bg5Btn   = document.querySelector('#switcher-background4');
    let img1Btn  = document.querySelector('#switcher-bg-img');
    let img2Btn  = document.querySelector('#switcher-bg-img1');
    let img3Btn  = document.querySelector('#switcher-bg-img2');
    let img4Btn  = document.querySelector('#switcher-bg-img3');
    let img5Btn  = document.querySelector('#switcher-bg-img4');
    let rAllBtn  = document.querySelector('#reset-all');
    let lEnBtn   = document.querySelector('#switcher-loader-enable');
    let lDiBtn   = document.querySelector('#switcher-loader-disable');

    // primary theme colors
    safeOn(p1Btn, 'click', () => {
        localStorage.setItem("primaryRGB", "42 ,16, 164");
        html.style.setProperty('--primary-rgb', '42 ,16, 164');
    });
    safeOn(p2Btn, 'click', () => {
        localStorage.setItem("primaryRGB", "125 ,0, 189");
        html.style.setProperty('--primary-rgb', '125 ,0, 189');
    });
    safeOn(p3Btn, 'click', () => {
        localStorage.setItem("primaryRGB", "4, 118, 141");
        html.style.setProperty('--primary-rgb', '4, 118, 141');
    });
    safeOn(p4Btn, 'click', () => {
        localStorage.setItem("primaryRGB", "138, 0, 32");
        html.style.setProperty('--primary-rgb', '138, 0, 32');
    });
    safeOn(p5Btn, 'click', () => {
        localStorage.setItem("primaryRGB", "9 ,124, 103");
        html.style.setProperty('--primary-rgb', '9 ,124, 103');
    });

    // bg colors (dark mode)
    function applyDarkBg(bodyRGB, bodyLightRGB) {
        html.setAttribute('data-theme-mode', 'dark');
        html.setAttribute('data-menu-styles', 'dark');
        html.setAttribute('data-header-styles', 'dark');
        document.querySelector('html').style.setProperty('--body-bg-rgb', bodyRGB);
        document.querySelector('html').style.setProperty('--body-bg-rgb2', bodyLightRGB);
        document.querySelector('html').style.setProperty('--light-rgb', bodyLightRGB);
        document.querySelector('html').style.setProperty('--form-control-bg', 'rgb(' + bodyLightRGB + ')');
        document.querySelector('html').style.setProperty('--input-border', 'rgba(255,255,255,0.1)');
        document.querySelector('html').style.setProperty('--gray-3', 'rgba(255,255,255,0.1)');
        let darkChk = document.querySelector('#switcher-dark-theme');
        if (darkChk) darkChk.checked = true;
        let menuDark = document.querySelector('#switcher-menu-dark');
        if (menuDark) menuDark.checked = true;
        let hdrDark = document.querySelector('#switcher-header-dark');
        if (hdrDark) hdrDark.checked = true;
        localStorage.setItem("fmsMenu", "dark");
        localStorage.setItem("fmsHeader", "dark");
    }

    safeOn(bg1Btn, 'click', () => {
        localStorage.setItem('bodyBgRGB', "0,8,52");
        localStorage.setItem('bodylightRGB', "14,22,66");
        applyDarkBg("0,8,52", "14,22,66");
    });
    safeOn(bg2Btn, 'click', () => {
        localStorage.setItem('bodyBgRGB', "58, 0, 109");
        localStorage.setItem('bodylightRGB', "72 ,14, 123");
        applyDarkBg("58, 0, 109", "72 ,14, 123");
    });
    safeOn(bg3Btn, 'click', () => {
        localStorage.setItem('bodyBgRGB', "0 ,59, 70");
        localStorage.setItem('bodylightRGB', "14, 73, 84");
        applyDarkBg("0 ,59, 70", "14, 73, 84");
    });
    safeOn(bg4Btn, 'click', () => {
        localStorage.setItem('bodyBgRGB', "65, 0, 0");
        localStorage.setItem('bodylightRGB', "79 ,14, 14");
        applyDarkBg("65, 0, 0", "79 ,14, 14");
    });
    safeOn(bg5Btn, 'click', () => {
        localStorage.setItem('bodyBgRGB', "1 ,77, 46");
        localStorage.setItem('bodylightRGB', "15 ,91, 60");
        applyDarkBg("1 ,77, 46", "15 ,91, 60");
    });

    // bg images
    safeOn(img1Btn, 'click', () => { html.setAttribute('data-bg-img', 'bgimg1'); localStorage.setItem("bgimg", "bgimg1"); });
    safeOn(img2Btn, 'click', () => { html.setAttribute('data-bg-img', 'bgimg2'); localStorage.setItem("bgimg", "bgimg2"); });
    safeOn(img3Btn, 'click', () => { html.setAttribute('data-bg-img', 'bgimg3'); localStorage.setItem("bgimg", "bgimg3"); });
    safeOn(img4Btn, 'click', () => { html.setAttribute('data-bg-img', 'bgimg4'); localStorage.setItem("bgimg", "bgimg4"); });
    safeOn(img5Btn, 'click', () => { html.setAttribute('data-bg-img', 'bgimg5'); localStorage.setItem("bgimg", "bgimg5"); });

    // light theme
    safeOn(lightBtn, 'click', () => {
        lightFn();
        if (window.FMSTheme) window.FMSTheme.setPreference('light');
        localStorage.setItem("fmsHeader", 'light');
        localStorage.removeItem("bodylightRGB");
        localStorage.removeItem("bodyBgRGB");
        localStorage.removeItem("fmsMenu");
        if (html.getAttribute('data-nav-layout') === 'horizontal') {
            html.setAttribute('data-header-styles', 'transparent');
        }
    });

    // dark theme
    safeOn(darkBtn, 'click', () => {
        darkFn();
        if (window.FMSTheme) window.FMSTheme.setPreference('dark');
        localStorage.setItem("fmsMenu", 'dark');
        localStorage.setItem("fmsHeader", 'transparent');
        if (html.getAttribute('data-nav-layout') === 'horizontal') {
            html.setAttribute('data-header-styles', 'dark');
        }
    });

    // menu styles
    safeOn(lmBtn, 'click', () => { html.setAttribute('data-menu-styles', 'light'); localStorage.setItem("fmsMenu", "light"); });
    safeOn(dmBtn, 'click', () => { html.setAttribute('data-menu-styles', 'dark');  localStorage.setItem("fmsMenu", "dark"); });
    safeOn(cmBtn, 'click', () => { html.setAttribute('data-menu-styles', 'color');  localStorage.setItem("fmsMenu", "color"); });
    safeOn(gmBtn, 'click', () => { html.setAttribute('data-menu-styles', 'gradient'); localStorage.setItem("fmsMenu", "gradient"); });
    safeOn(tmBtn, 'click', () => { html.setAttribute('data-menu-styles', 'transparent'); localStorage.setItem("fmsMenu", "transparent"); });

    // header styles
    safeOn(lhBtn, 'click', () => { html.setAttribute('data-header-styles', 'light'); localStorage.setItem("fmsHeader", "light"); });
    safeOn(dhBtn, 'click', () => { html.setAttribute('data-header-styles', 'dark');  localStorage.setItem("fmsHeader", "dark"); });
    safeOn(chBtn, 'click', () => { html.setAttribute('data-header-styles', 'color');  localStorage.setItem("fmsHeader", "color"); });
    safeOn(ghBtn, 'click', () => { html.setAttribute('data-header-styles', 'gradient'); localStorage.setItem("fmsHeader", "gradient"); });
    safeOn(thBtn, 'click', () => { html.setAttribute('data-header-styles', 'transparent'); localStorage.setItem("fmsHeader", "transparent"); });

    // layout width
    safeOn(dwBtn, 'click', () => {
        html.setAttribute('data-width', 'default');
        localStorage.setItem("fmsdefaultwidth", true);
        localStorage.removeItem("fmsboxed");
        localStorage.removeItem("fmsfullwidth");
    });
    safeOn(fwBtn, 'click', () => {
        html.setAttribute('data-width', 'fullwidth');
        localStorage.setItem("fmsfullwidth", true);
        localStorage.removeItem("fmsboxed");
        localStorage.removeItem("fmsdefaultwidth");
    });
    safeOn(bxBtn, 'click', () => {
        html.setAttribute('data-width', 'boxed');
        localStorage.setItem("fmsboxed", true);
        localStorage.removeItem("fmsfullwidth");
        localStorage.removeItem("fmsdefaultwidth");
        if (typeof checkHoriMenu === 'function') checkHoriMenu();
    });

    // page style
    safeOn(flatBtn, 'click', () => {
        html.setAttribute('data-page-style', 'flat');
        localStorage.setItem("fmsflat", true);
        localStorage.removeItem("fmsclassic");
        localStorage.removeItem("fmsmodern");
        localStorage.removeItem("fmsregular");
        let c = document.querySelector('.page-container');
        if (c) c.classList.add('main-body-container');
    });
    safeOn(regBtn, 'click', () => {
        html.setAttribute('data-page-style', 'regular');
        localStorage.setItem("fmsregular", true);
        localStorage.removeItem("fmsclassic");
        localStorage.removeItem("fmsmodern");
        localStorage.removeItem("fmsflat");
        let c = document.querySelector('.page-container');
        if (c) c.classList.remove('main-body-container');
    });
    safeOn(clsBtn, 'click', () => {
        html.setAttribute('data-page-style', 'classic');
        localStorage.setItem("fmsclassic", true);
        localStorage.removeItem("fmsregular");
        localStorage.removeItem("fmsmodern");
        localStorage.removeItem("fmsflat");
        let c = document.querySelector('.page-container');
        if (c) c.classList.remove('main-body-container');
    });
    safeOn(modBtn, 'click', () => {
        html.setAttribute('data-page-style', 'modern');
        localStorage.setItem("fmsmodern", true);
        localStorage.removeItem("fmsregular");
        localStorage.removeItem("fmsclassic");
        localStorage.removeItem("fmsflat");
        let c = document.querySelector('.page-container');
        if (c) c.classList.remove('main-body-container');
    });

    // header/menu position
    safeOn(fhBtn, 'click', () => {
        html.setAttribute('data-header-position', 'fixed');
        localStorage.setItem("fmsheaderfixed", true);
        localStorage.removeItem("fmsheaderscrollable");
    });
    safeOn(shBtn, 'click', () => {
        html.setAttribute('data-header-position', 'scrollable');
        localStorage.setItem("fmsheaderscrollable", true);
        localStorage.removeItem("fmsheaderfixed");
    });
    safeOn(fmBtn, 'click', () => {
        html.setAttribute('data-menu-position', 'fixed');
        localStorage.setItem("fmsmenufixed", true);
        localStorage.removeItem("fmsmenuscrollable");
    });
    safeOn(smBtn, 'click', () => {
        html.setAttribute('data-menu-position', 'scrollable');
        localStorage.setItem("fmsmenuscrollable", true);
        localStorage.removeItem("fmsmenufixed");
    });

    // sidemenu layout
    safeOn(defBtn, 'click', () => {
        html.setAttribute('data-vertical-style', 'default');
        html.setAttribute('data-nav-layout', 'vertical');
        if (typeof toggleSidemenu === 'function') toggleSidemenu();
        localStorage.removeItem("fmsverticalstyles");
        document.querySelectorAll(".main-menu>li.open").forEach((ele) => {
            if (!ele.classList.contains('active')) {
                ele.classList.remove('open');
                let sub = ele.querySelector('ul');
                if (sub) sub.style.display = 'none';
            }
        });
    });
    safeOn(clBtn, 'click', () => {
        if (typeof closedSidemenuFn === 'function') closedSidemenuFn();
        localStorage.setItem("fmsverticalstyles", 'closed');
        document.querySelectorAll(".main-menu>li.open").forEach((ele) => {
            if (!ele.classList.contains('active')) {
                ele.classList.remove('open');
                let sub = ele.querySelector('ul');
                if (sub) sub.style.display = 'none';
            }
        });
    });
    safeOn(dtBtn, 'click', () => { if (typeof detachedFn === 'function') detachedFn(); localStorage.setItem("fmsverticalstyles", 'detached'); });
    safeOn(itBtn, 'click', () => { if (typeof iconTextFn === 'function') iconTextFn(); localStorage.setItem("fmsverticalstyles", 'icontext'); });
    safeOn(ovBtn, 'click', () => {
        if (typeof iconOverayFn === 'function') iconOverayFn();
        localStorage.setItem("fmsverticalstyles", 'overlay');
        document.querySelectorAll(".main-menu>li.open").forEach((ele) => {
            if (!ele.classList.contains('active')) {
                ele.classList.remove('open');
                let sub = ele.querySelector('ul');
                if (sub) sub.style.display = 'none';
            }
        });
    });
    safeOn(dbBtn, 'click', () => { if (typeof doubletFn === 'function') doubletFn(); localStorage.setItem("fmsverticalstyles", 'doublemenu'); });
    safeOn(mcBtn, 'click', () => {
        html.removeAttribute('data-vertical-style');
        if (typeof menuClickFn === 'function') menuClickFn();
        localStorage.setItem("fmsnavstyles", 'menu-click');
        localStorage.removeItem("fmsverticalstyles");
        document.querySelectorAll(".main-menu>li.open").forEach((ele) => {
            if (!ele.classList.contains('active')) {
                ele.classList.remove('open');
                let sub = ele.querySelector('ul');
                if (sub) sub.style.display = 'none';
            }
        });
        if (html.getAttribute("data-nav-layout") === 'horizontal') {
            let mm = document.querySelector(".main-menu");
            if (mm) { mm.style.marginLeft = "0px"; mm.style.marginRight = "0px"; }
            if (typeof ResizeMenu === 'function') ResizeMenu();
        }
    });
    safeOn(mhBtn, 'click', () => {
        html.removeAttribute('data-vertical-style');
        if (typeof menuhoverFn === 'function') menuhoverFn();
        localStorage.setItem("fmsnavstyles", 'menu-hover');
        localStorage.removeItem("fmsverticalstyles");
        if (html.getAttribute("data-nav-layout") === 'horizontal') {
            let mm = document.querySelector(".main-menu");
            if (mm) { mm.style.marginLeft = "0px"; mm.style.marginRight = "0px"; }
            if (typeof ResizeMenu === 'function') ResizeMenu();
        }
    });
    safeOn(icBtn, 'click', () => {
        html.removeAttribute('data-vertical-style');
        if (typeof iconClickFn === 'function') iconClickFn();
        localStorage.setItem("fmsnavstyles", 'icon-click');
        localStorage.removeItem("fmsverticalstyles");
        if (html.getAttribute("data-nav-layout") === 'horizontal') {
            let mm = document.querySelector(".main-menu");
            if (mm) { mm.style.marginLeft = "0px"; mm.style.marginRight = "0px"; }
            if (typeof ResizeMenu === 'function') ResizeMenu();
        }
        let sl = document.querySelector("#slide-left");
        if (sl) sl.classList.add("d-none");
        document.querySelectorAll(".main-menu>li.open").forEach((ele) => {
            if (!ele.classList.contains('active')) {
                ele.classList.remove('open');
                let sub = ele.querySelector('ul');
                if (sub) sub.style.display = 'none';
            }
        });
    });
    safeOn(ihBtn, 'click', () => {
        html.removeAttribute('data-vertical-style');
        if (typeof iconHoverFn === 'function') iconHoverFn();
        localStorage.setItem("fmsnavstyles", 'icon-hover');
        localStorage.removeItem("fmsverticalstyles");
        if (html.getAttribute("data-nav-layout") === 'horizontal') {
            let mm = document.querySelector(".main-menu");
            if (mm) { mm.style.marginLeft = "0px"; mm.style.marginRight = "0px"; }
            if (typeof ResizeMenu === 'function') ResizeMenu();
        }
        let sl = document.querySelector("#slide-left");
        if (sl) sl.classList.add("d-none");
    });

    // vertical/horizontal
    safeOn(vBtn, 'click', () => {
        let mc = document.querySelector('.main-content');
        localStorage.removeItem("fmslayout");
        localStorage.setItem("fmsverticalstyles", 'doublemenu');
        if (typeof verticalFn === 'function') verticalFn();
        if (typeof setNavActive === 'function') setNavActive();
        if (mc) mc.removeEventListener('click', clearNavDropdown);
        let mm = document.querySelector(".main-menu");
        if (mm) { mm.style.marginLeft = "0px"; mm.style.marginRight = "0px"; }
        document.querySelectorAll(".slide").forEach((e) => {
            if (e.classList.contains("open") && !e.classList.contains("active")) {
                let sub = e.querySelector("ul");
                if (sub) sub.style.display = "none";
            }
        });
    });
    safeOn(hBtn, 'click', () => {
        let mc = document.querySelector('.main-content');
        html.removeAttribute('data-vertical-style');
        localStorage.setItem("fmslayout", 'horizontal');
        localStorage.removeItem("fmsverticalstyles");
        if (html.getAttribute('data-theme-mode') === 'light') {
            html.setAttribute('data-header-styles', 'transparent');
            html.setAttribute('data-menu-styles', 'transparent');
            localStorage.setItem("fmsMenu", '\ttransparent');
        } else if (html.getAttribute('data-theme-mode') === 'dark') {
            html.setAttribute('data-header-styles', 'dark');
        }
        if (typeof horizontalClickFn === 'function') horizontalClickFn();
        clearNavDropdown();
        if (mc) mc.addEventListener('click', clearNavDropdown);
    });

    // rtl/ltr
    safeOn(rtlBtn, 'click', () => {
        localStorage.setItem("fmsrtl", true);
        localStorage.removeItem("fmsltr");
        if (typeof rtlFn === 'function') rtlFn();
        document.querySelectorAll(".noUi-target").forEach((e) => {
            e.querySelectorAll(".noUi-origin").forEach((orig) => { orig.classList.add("transform-none"); });
        });
    });
    safeOn(ltrBtn, 'click', () => {
        localStorage.setItem("fmsltr", true);
        localStorage.removeItem("fmsrtl");
        if (typeof ltrFn === 'function') ltrFn();
        document.querySelectorAll(".noUi-target").forEach((e) => {
            e.querySelectorAll(".noUi-origin").forEach((orig) => { orig.classList.remove("transform-none"); });
        });
    });

    // reset all
    safeOn(rAllBtn, 'click', () => {
        ResetAllFn();
        if (typeof setNavActive === 'function') setNavActive();
        let mt = document.querySelector('#switcher-menu-transparent');
        if (mt) mt.checked = true;
        document.querySelectorAll(".slide").forEach((e) => {
            if (e.classList.contains("open") && !e.classList.contains("active")) {
                let sub = e.querySelector("ul");
                if (sub) sub.style.display = "none";
            }
        });
    });

    // loader
    if (lEnBtn) lEnBtn.onclick = () => {
        html.setAttribute("loader", "enable");
        localStorage.setItem("loaderEnable", "true");
    };
    if (lDiBtn) lDiBtn.onclick = () => {
        html.setAttribute("loader", "disable");
        localStorage.setItem("loaderEnable", "false");
    };
}

function ltrFn() {
    let html = document.querySelector('html');
    if (!document.querySelector("#style")?.href.includes('bootstrap.min.css')) {
        let s = document.querySelector("#style");
        if (s) s.setAttribute("href", "../assets/libs/bootstrap/css/bootstrap.min.css");
    }
    html.setAttribute("dir", "ltr");
    let ltr = document.querySelector('#switcher-ltr');
    if (ltr) ltr.checked = true;
    checkOptions();
}

function rtlFn() {
    let html = document.querySelector('html');
    html.setAttribute("dir", "rtl");
    let s = document.querySelector("#style");
    if (s) s.setAttribute("href", "../assets/libs/bootstrap/css/bootstrap.rtl.min.css");
    checkOptions();
}

function lightFn() {
    let html = document.querySelector('html');
    html.setAttribute('data-theme-mode', 'light');
    html.setAttribute('data-header-styles', 'transparent');
    html.setAttribute('data-menu-styles', 'transparent');
    if (!localStorage.getItem('primaryRGB')) { html.setAttribute('style', ''); }
    let lChk = document.querySelector('#switcher-light-theme');
    if (lChk) lChk.checked = true;
    let mt = document.querySelector('#switcher-menu-transparent');
    if (mt) mt.checked = true;
    let ht = document.querySelector('#switcher-header-transparent');
    if (ht) ht.checked = true;
    localStorage.removeItem("fmsdarktheme");
    localStorage.removeItem("fmsbgColor");
    localStorage.removeItem("fmsheaderbg");
    localStorage.removeItem("fmsbgwhite");
    localStorage.removeItem("fmsmenubg");
    checkOptions();
    html.style.removeProperty('--body-bg-rgb');
    html.style.removeProperty('--body-bg-rgb2');
    html.style.removeProperty("--light-rgb");
    html.style.removeProperty("--form-control-bg");
    html.style.removeProperty("--gray-3");
    html.style.removeProperty("--input-border");
    ['#switcher-background4','#switcher-background3','#switcher-background2','#switcher-background1','#switcher-background']
        .forEach((sel) => { let e = document.querySelector(sel); if (e) e.checked = false; });
    if (mt) mt.checked = true;
    if (ht) ht.checked = true;
}

function darkFn() {
    let html = document.querySelector('html');
    html.setAttribute('data-theme-mode', 'dark');
    html.setAttribute('data-header-styles', 'transparent');
    html.setAttribute('data-menu-styles', 'dark');
    if (!localStorage.getItem('primaryRGB')) { html.setAttribute('style', ''); }
    let dm = document.querySelector('#switcher-menu-dark');
    if (dm) dm.checked = true;
    let dh = document.querySelector('#switcher-header-dark');
    if (dh) dh.checked = true;
    ['--body-bg-rgb','--body-bg-rgb2','--light-rgb','--form-control-bg','--gray-3','--input-border']
        .forEach((p) => html.style.removeProperty(p));
    localStorage.setItem("fmsdarktheme", true);
    localStorage.removeItem("fmslighttheme");
    localStorage.removeItem("bodyBgRGB");
    localStorage.removeItem("fmsbgColor");
    localStorage.removeItem("fmsheaderbg");
    localStorage.removeItem("fmsbgwhite");
    localStorage.removeItem("fmsmenubg");
    checkOptions();
    ['#switcher-background4','#switcher-background3','#switcher-background2','#switcher-background1','#switcher-background']
        .forEach((sel) => { let e = document.querySelector(sel); if (e) e.checked = false; });
    if (dm) dm.checked = true;
    let ht = document.querySelector('#switcher-header-transparent');
    if (ht) ht.checked = true;
}

function verticalFn() {
    let html = document.querySelector('html');
    html.setAttribute('data-nav-layout', 'vertical');
    html.setAttribute('data-vertical-style', 'doublemenu');
    html.setAttribute('data-toggled', 'double-menu-open');
    html.removeAttribute('data-nav-style');
    localStorage.removeItem('fmsnavstyles');
    let vb = document.querySelector('#switcher-vertical');
    if (vb) vb.checked = true;
    let mc = document.querySelector('#switcher-menu-click');
    if (mc) mc.checked = false;
    let mh = document.querySelector('#switcher-menu-hover');
    if (mh) mh.checked = false;
    let ic = document.querySelector('#switcher-icon-click');
    if (ic) ic.checked = false;
    let ih = document.querySelector('#switcher-icon-hover');
    if (ih) ih.checked = false;
    checkOptions();
}

function horizontalClickFn() {
    let vb = document.querySelector('#switcher-horizontal');
    if (vb) vb.checked = true;
    let mc = document.querySelector('#switcher-menu-click');
    if (mc) mc.checked = true;
    localStorage.setItem("fmsnavstyles", 'menu-click');
    let html = document.querySelector('html');
    html.setAttribute('data-nav-layout', 'horizontal');
    html.removeAttribute('data-vertical-style');
    if (!html.getAttribute('data-nav-style')) { html.setAttribute('data-nav-style', 'menu-click'); }
    if (!localStorage.fmsMenu && !localStorage.bodylightRGB) {
        html.setAttribute("data-menu-styles", "transparent");
        let mt = document.querySelector('#switcher-menu-transparent');
        if (mt) mt.checked = true;
        checkOptions();
    }
    checkOptions();
    if (typeof checkHoriMenu === 'function') checkHoriMenu();
}

function ResetAllFn() {
    let html = document.querySelector('html');
    if (localStorage.getItem("fmslayout") === "horizontal") {
        let mm = document.querySelector(".main-menu");
        if (mm) mm.style.display = "block";
    }
    checkOptions();
    localStorage.clear();
    lightFn();
    html.removeAttribute("style");
    html.removeAttribute('data-nav-style');
    html.removeAttribute('data-menu-position');
    html.removeAttribute('data-header-position');
    html.removeAttribute('data-page-style');
    html.removeAttribute('data-width');
    html.removeAttribute('data-bg-img');
    html.style.removeProperty('--primary-rgb');
    html.style.removeProperty('--body-bg-rgb');
    if (typeof ltrFn === 'function') ltrFn();
    if (typeof doubletFn === 'function') doubletFn();
    let mc = document.querySelector('.main-content');
    if (typeof clearNavDropdown === 'function' && mc) mc.removeEventListener('click', clearNavDropdown);
    let cls = document.querySelector('#switcher-classic');
    if (cls) cls.checked = false;
    let mod = document.querySelector('#switcher-modern');
    if (mod) mod.checked = false;
    let flat = document.querySelector('#switcher-flat');
    if (flat) flat.checked = true;
    let reg = document.querySelector('#switcher-regular');
    if (reg) reg.checked = false;
    let dw = document.querySelector('#switcher-default-width');
    if (dw) dw.checked = false;
    let fw = document.querySelector('#switcher-full-width');
    if (fw) fw.checked = true;
    let bx = document.querySelector('#switcher-boxed');
    if (bx) bx.checked = false;
    let fm = document.querySelector('#switcher-menu-fixed');
    if (fm) fm.checked = true;
    let sm = document.querySelector('#switcher-menu-scroll');
    if (sm) sm.checked = false;
    let fh = document.querySelector('#switcher-header-fixed');
    if (fh) fh.checked = true;
    let sh = document.querySelector('#switcher-header-scroll');
    if (sh) sh.checked = false;
    let def = document.querySelector('#switcher-default-menu');
    if (def) def.checked = false;
    let cl = document.querySelector('#switcher-closed-menu');
    if (cl) cl.checked = false;
    let it = document.querySelector('#switcher-icontext-menu');
    if (it) it.checked = false;
    let ov = document.querySelector('#switcher-icon-overlay');
    if (ov) ov.checked = false;
    let dt = document.querySelector('#switcher-detached');
    if (dt) dt.checked = false;
    let db = document.querySelector('#switcher-double-menu');
    if (db) db.checked = true;
    ['#switcher-primary','#switcher-primary1','#switcher-primary2','#switcher-primary3','#switcher-primary4',
     '#switcher-background','#switcher-background1','#switcher-background2','#switcher-background3','#switcher-background4']
        .forEach((sel) => { let e = document.querySelector(sel); if (e) e.checked = false; });
    let mm = document.querySelector(".main-menu");
    if (mm) { mm.style.marginLeft = "0px"; mm.style.marginRight = "0px"; }
}

function checkOptions() {
    let html = document.querySelector('html');
    if (localStorage.getItem('fmsdarktheme')) {
        let d = document.querySelector('#switcher-dark-theme');
        if (d) d.checked = true;
    }
    if (localStorage.getItem('fmslayout') === "horizontal") {
        let h = document.querySelector('#switcher-horizontal');
        if (h) h.checked = true;
        let mc = document.querySelector('#switcher-menu-click');
        if (mc) mc.checked = true;
    } else {
        let v = document.querySelector('#switcher-vertical');
        if (v) v.checked = true;
    }
    if (localStorage.getItem('fmsrtl')) {
        let r = document.querySelector('#switcher-rtl');
        if (r) r.checked = true;
    } else {
        let l = document.querySelector('#switcher-ltr');
        if (l) l.checked = true;
    }

    let headerChecks = {
        'light': '#switcher-header-light',
        'color': '#switcher-header-primary',
        'gradient': '#switcher-header-gradient',
        'dark': '#switcher-header-dark',
        'transparent': '#switcher-header-transparent',
    };
    Object.entries(headerChecks).forEach(([val, sel]) => {
        if (localStorage.getItem('fmsHeader') === val) {
            let e = document.querySelector(sel);
            if (e) e.checked = true;
        }
    });

    let menuChecks = {
        'light': '#switcher-menu-light',
        'color': '#switcher-menu-primary',
        'gradient': '#switcher-menu-gradient',
        'dark': '#switcher-menu-dark',
        'transparent': '#switcher-menu-transparent',
    };
    Object.entries(menuChecks).forEach(([val, sel]) => {
        if (localStorage.getItem('fmsMenu') === val) {
            let e = document.querySelector(sel);
            if (e) e.checked = true;
        }
    });

    if (localStorage.getItem('fmsdefaultwidth')) { let e = document.querySelector('#switcher-default-width'); if (e) e.checked = true; }
    if (localStorage.getItem('fmsfullwidth')) { let e = document.querySelector('#switcher-full-width'); if (e) e.checked = true; }
    if (localStorage.getItem('fmsboxed')) { let e = document.querySelector('#switcher-boxed'); if (e) e.checked = true; }
    if (localStorage.getItem('fmsheaderscrollable')) { let e = document.querySelector('#switcher-header-scroll'); if (e) e.checked = true; }
    if (localStorage.getItem('fmsmenuscrollable')) { let e = document.querySelector('#switcher-menu-scroll'); if (e) e.checked = true; }
    if (localStorage.getItem('fmsheaderfixed')) { let e = document.querySelector('#switcher-header-fixed'); if (e) e.checked = true; }
    if (localStorage.getItem('fmsmenufixed')) { let e = document.querySelector('#switcher-menu-fixed'); if (e) e.checked = true; }

    let pageStyles = {
        'regular': '#switcher-regular',
        'classic': '#switcher-classic',
        'modern': '#switcher-modern',
        'flat': '#switcher-flat',
    };
    Object.entries(pageStyles).forEach(([val, sel]) => {
        if (localStorage.getItem('fms' + val)) {
            let e = document.querySelector(sel);
            if (e) e.checked = true;
            if (val !== 'flat') {
                let c = document.querySelector('.page-container');
                if (c) c.classList.remove('main-body-container');
            } else {
                let c = document.querySelector('.page-container');
                if (c) c.classList.add('main-body-container');
            }
        }
    });

    let vsStyles = {
        'default': '#switcher-default-menu',
        'closed': '#switcher-closed-menu',
        'icontext': '#switcher-icontext-menu',
        'overlay': '#switcher-icon-overlay',
        'detached': '#switcher-detached',
        'doublemenu': '#switcher-double-menu',
    };
    if (localStorage.fmsverticalstyles) {
        let sel = vsStyles[localStorage.getItem('fmsverticalstyles')];
        if (sel) { let e = document.querySelector(sel); if (e) e.checked = true; }
    }

    let navStyles = {
        'menu-click': '#switcher-menu-click',
        'menu-hover': '#switcher-menu-hover',
        'icon-click': '#switcher-icon-click',
        'icon-hover': '#switcher-icon-hover',
    };
    if (localStorage.fmsnavstyles) {
        let sel = navStyles[localStorage.getItem('fmsnavstyles')];
        if (sel) { let e = document.querySelector(sel); if (e) e.checked = true; }
    }

    if (localStorage.loaderEnable !== "true") { let e = document.querySelector("#switcher-loader-disable"); if (e) e.checked = true; }
}

function localStorageBackup2() {
    if (localStorage.bodyBgRGB || localStorage.bodylightRGB) {
        let d = document.querySelector('#switcher-dark-theme');
        if (d) d.checked = true;
        let md = document.querySelector('#switcher-menu-dark');
        if (md) md.checked = true;
        let hd = document.querySelector('#switcher-header-transparent');
        if (hd) hd.checked = true;
    }

    let bgMap = {
        "0,8,52": "#switcher-background",
        "58, 0, 109": "#switcher-background1",
        "0 ,59, 70": "#switcher-background2",
        "65, 0, 0": "#switcher-background3",
        "1 ,77, 46": "#switcher-background4",
    };
    if (localStorage.bodyBgRGB && localStorage.bodylightRGB) {
        let sel = bgMap[localStorage.bodyBgRGB];
        if (sel) { let e = document.querySelector(sel); if (e) e.checked = true; }
    }

    let pMap = {
        "42 ,16, 164": "#switcher-primary",
        "125 ,0, 189": "#switcher-primary1",
        "4, 118, 141": "#switcher-primary2",
        "138, 0, 32": "#switcher-primary3",
        "9 ,124, 103": "#switcher-primary4",
    };
    if (localStorage.primaryRGB) {
        let sel = pMap[localStorage.primaryRGB];
        if (sel) { let e = document.querySelector(sel); if (e) e.checked = true; }
    }

    if (localStorage.loaderEnable === "true") { let e = document.querySelector("#switcher-loader-enable"); if (e) e.checked = true; }
}
